import React from 'react';
import { useAuth } from '../../context/AuthContext';
import { useTransactions } from '../../context/TransactionContext';
import { Link } from 'react-router-dom';

function Home() {
  const { user } = useAuth();
  const { transactions } = useTransactions();

  // Get recent transactions
  const recentTransactions = transactions
    .slice(0, 5)
    .sort((a, b) => new Date(b.date) - new Date(a.date));

  return (
    <div className="dashboard">
      {/* User Welcome */}
      <section className="welcome">
        <h2>Welcome, {user?.name}</h2>
        <div className="balance">
          <h3>Your Balance</h3>
          <p className="amount">$1,000.00</p>
        </div>
      </section>

      {/* Quick Actions */}
      <section className="actions">
        <Link to="/send" className="action-button">Send Money</Link>
        <Link to="/receive" className="action-button">Request Money</Link>
      </section>

      {/* Recent Transactions */}
      <section className="recent-transactions">
        <h3>Recent Transactions</h3>
        <div className="transactions-list">
          {recentTransactions.map(transaction => (
            <div key={transaction.id} className="transaction-item">
              <div className="transaction-info">
                <p>{transaction.type === 'send' ? 'Sent to' : 'Received from'}</p>
                <p>{transaction.recipient || transaction.sender}</p>
              </div>
              <p className="amount">${transaction.amount}</p>
            </div>
          ))}
        </div>
        <Link to="/transactions" className="view-all">View All Transactions</Link>
      </section>
    </div>
  );
}

export default Home;
